use std::hash::{DefaultHasher, Hash, Hasher};
use strum::VariantArray;
use strum_macros::VariantArray;

#[derive(VariantArray, Clone, Copy)]
pub enum WelcomeDoc {
    /// generated by username: `test0`
    NoWelcomeDoc,

    /// generated by username: `test1`
    OldWelcomeDoc,

    /// generated by username: `test5`
    HypeWelcomeDoc,

    /// generated by username: `test2`
    FramgentedArchetypes,
}

pub fn cohort<E: VariantArray + Copy>(username: &str) -> E {
    let mut hasher = DefaultHasher::new();
    username.hash(&mut hasher);
    let hash = hasher.finish();

    let variant_id = (hash % E::VARIANTS.len() as u64) as usize;

    E::VARIANTS[variant_id]
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Cohorts are recomputed from usernames long after signup, so the hash
    /// must never change: a new Rust release or a code change here would
    /// reshuffle every experiment's arms.
    #[test]
    fn assignments_are_stable() {
        let arms: String = (0..32)
            .map(|i| (cohort::<WelcomeDoc>(&format!("user{i}")) as usize).to_string())
            .collect();
        assert_eq!(arms, "23202200310101001212012201201111");
    }
}
